CREATE TABLE IF NOT EXISTS affiliates(id TEXT PRIMARY KEY,user_id TEXT NOT NULL UNIQUE,public_code TEXT NOT NULL UNIQUE,status TEXT NOT NULL DEFAULT 'pending',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS affiliate_attributions(id TEXT PRIMARY KEY,affiliate_id TEXT NOT NULL,visitor_token TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,expires_at TEXT);
CREATE TABLE IF NOT EXISTS commission_rules(id TEXT PRIMARY KEY,product_id TEXT NOT NULL,percent_basis_points INTEGER NOT NULL DEFAULT 0,fixed_cents INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'active');
CREATE TABLE IF NOT EXISTS commissions(id TEXT PRIMARY KEY,affiliate_id TEXT NOT NULL,order_id TEXT NOT NULL,amount_cents INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'pending',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
